functions.bhshell_read_line:
char *bhshell_read_line()
{
    str s = {.items = ((void *)0), .position = 0, .bufsize = 0};
    while (1)
    {
        int c = getchar();
        if (c == '\n' || c == (-1))
        {
            char *string = get_string(&s);
            return string;
        }
        else
        {
            do
            {
                if ((&s)->position >= (&s)->bufsize)
                {
                    if ((&s)->bufsize == 0)
                        (&s)->bufsize = 16;
                    else
                        (&s)->bufsize *= 2;
                    (&s)->items = xrealloc((&s)->items, ((&s)->bufsize) * sizeof(*(&s)->items));
                }
                (&s)->items[(&s)->position++] = c;
            } while (0);
        }
    }
}

