void bhshell_loop()
{
    char **args;
    int status = 1;
    do
    {
        char *dir = getcwd(((void *)0), 0);
        if (!dir)
            exit(1);
        printf("[%s] $ ", dir);
        char *line = bhshell_read_line();
        command *cmd = bhshell_parse(line);
        if (cmd == ((void *)0))
        {
            printf("Invalid Command\n");
            continue;
        }
        status = bhshell_execute(cmd);
        free(dir);
        free(line);
        destroy_command(cmd);
    } while (status);
}

functions.bhshell_execute:
int bhshell_execute(command *cmd)
{
    if (cmd->args[0] == ((void *)0))
    {
        return 1;
    }
    for (int i = 0; i < bhshell_num_builtins(); i++)
    {
        if (strcmp(cmd->args[0], bhshell_builtin_str[i]) == 0)
        {
            return (*bhshell_builtin_func[i])(cmd->args);
        }
    }
    return bhshell_launch(cmd);
}

functions.bhshell_launch:
int bhshell_launch(command *cmd)
{
    pid_t pid;
    int status;
    int redirect_fd[2];
    if (cmd->redirect_file_name != ((void *)0))
    {
        if (pipe(redirect_fd) == -1)
        {
            exit(1);
        }
    }
    int pipe_fd[2];
    if (cmd->pipe_args != ((void *)0))
    {
        if (pipe(pipe_fd) == -1)
        {
            exit(1);
        }
    }
    pid = fork();
    if (pid == 0)
    {
        if (cmd->pipe_args != ((void *)0))
        {
            close(pipe_fd[0]);
            if (dup2(pipe_fd[1], 1) == -1)
            {
                fprintf(stderr, "bhshell: Could not redirect stdout\n");
                exit(1);
            }
            close(pipe_fd[1]);
            if (cmd->redirect_file_name != ((void *)0))
            {
                close(redirect_fd[0]);
                close(redirect_fd[1]);
            }
        }
        if (cmd->pipe_args == ((void *)0) && cmd->redirect_file_name != ((void *)0))
        {
            close(redirect_fd[0]);
            if (dup2(redirect_fd[1], 1) == -1)
            {
                fprintf(stderr, "bhshell: Could not redirect stdout to file\n");
                exit(1);
            }
            close(redirect_fd[1]);
        }
        if (execvp(cmd->args[0], cmd->args) == -1)
        {
            perror("bhshell");
        }
        exit(1);
    }
    else if (pid < 0)
    {
        perror("bhshell: Could not create child process");
        exit(1);
    }
    if (cmd->pipe_args != ((void *)0))
    {
        pid_t pid_pipe = fork();
        int pipe_status;
        if (pid_pipe == 0)
        {
            if (cmd->redirect_file_name != ((void *)0))
            {
                close(redirect_fd[0]);
                if (dup2(redirect_fd[1], 1) == -1)
                {
                    fprintf(stderr, "bhshell: Could not redirect stdout to file\n");
                    exit(1);
                }
                close(redirect_fd[1]);
            }
            close(pipe_fd[1]);
            if (dup2(pipe_fd[0], 0) == -1)
            {
                fprintf(stderr, "bhshell: Could not redirect stdin\n");
                exit(1);
            }
            close(pipe_fd[0]);
            if (execvp(cmd->pipe_args[0], cmd->pipe_args) == -1)
            {
                perror("bhshell");
            }
            exit(1);
        }
        else if (pid_pipe < 0)
        {
            perror("bhshell: Could not create child process");
            exit(1);
        }
        close(pipe_fd[0]);
        close(pipe_fd[1]);
        if (cmd->redirect_file_name != ((void *)0))
        {
            write_to_redirect(redirect_fd, cmd);
        }
        do
        {
            waitpid(pid_pipe, &pipe_status, 2);
            waitpid(pid, &status, 2);
        } while (!(((status) & 0x7f) == 0) && !(((signed char)(((status) & 0x7f) + 1) >> 1) > 0) &&
                 !(((pipe_status) & 0x7f) == 0) && !(((signed char)(((pipe_status) & 0x7f) + 1) >> 1) > 0));
        return 1;
    }
    else if (cmd->redirect_file_name != ((void *)0))
    {
        write_to_redirect(redirect_fd, cmd);
    }
    do
    {
        waitpid(pid, &status, 2);
    } while (!(((status) & 0x7f) == 0) && !(((signed char)(((status) & 0x7f) + 1) >> 1) > 0));
    return 1;
}

