functions.write_to_redirect:
void write_to_redirect(int redirect_fd[2], command *cmd)
{
    str s = {.items = ((void *)0), .position = 0, .bufsize = 0};
    char temp;
    close(redirect_fd[1]);
    int finished = read(redirect_fd[0], &temp, sizeof(char));
    if (finished == -1)
    {
        close(redirect_fd[0]);
        close(redirect_fd[1]);
        free(s.items);
        exit(1);
    }
    while (finished != 0)
    {
        do
        {
            if ((&s)->position >= (&s)->bufsize)
            {
                if ((&s)->bufsize == 0)
                    (&s)->bufsize = 16;
                else
                    (&s)->bufsize *= 2;
                (&s)->items = xrealloc((&s)->items, ((&s)->bufsize) * sizeof(*(&s)->items));
            }
            (&s)->items[(&s)->position++] = temp;
        } while (0);
        finished = read(redirect_fd[0], &temp, sizeof(char));
    }
    char *string = get_string(&s);
    close(redirect_fd[0]);
    FILE *f = fopen(cmd->redirect_file_name, "w");
    if (!f)
    {
        fprintf(stderr, "Could not open file\n");
        free(s.items);
        exit(1);
    }
    size_t written = fwrite(string, strlen(string), 1, f);
    if (written == 0)
    {
        fprintf(stderr, "Could not write to file\n");
        free(string);
        exit(1);
    }
    free(string);
    fclose(f);
}

