char *get_string(str *s)
{
    do
    {
        if ((s)->position >= (s)->bufsize)
        {
            if ((s)->bufsize == 0)
                (s)->bufsize = 16;
            else
                (s)->bufsize *= 2;
            (s)->items = xrealloc((s)->items, ((s)->bufsize) * sizeof(*(s)->items));
        }
        (s)->items[(s)->position++] = '\0';
    } while (0);
    char *string = xmalloc(sizeof(char) * (s->position));
    memcpy(string, s->items, sizeof(char) * s->position);
    free(s->items);
    s->position = 0;
    s->items = ((void *)0);
    s->bufsize = 0;
    return string;
}

functions.destroy_args:
void destroy_args(char **args)
{
    if (!args)
        return;
    size_t i = 0;
    while (args[i] != ((void *)0))
    {
        free(args[i]);
        i++;
    }
}

functions.get_args:
char **get_args(arg_list *l)
{
    if (l->position == 0)
    {
        return ((void *)0);
    }
    do
    {
        if ((l)->position >= (l)->bufsize)
        {
            if ((l)->bufsize == 0)
                (l)->bufsize = 16;
            else
                (l)->bufsize *= 2;
            (l)->items = xrealloc((l)->items, ((l)->bufsize) * sizeof(*(l)->items));
        }
        (l)->items[(l)->position++] = ((void *)0);
    } while (0);
    char **args = xmalloc(sizeof(char *) * (l->position));
    for (size_t i = 0; i < l->position - 1; i++)
    {
        size_t length = strlen(l->items[i]);
        args[i] = xmalloc(sizeof(char) * (length + 1));
        memcpy(args[i], l->items[i], length + 1);
    }
    args[l->position - 1] = ((void *)0);
    return args;
}

